type Address = { cep: string; street: string; district: string; city: string; state: string };

const providers: Array<(cep: string) => Promise<Address>> = [
  async (cep) => {
    const data = await getJson(`https://viacep.com.br/ws/${cep}/json/`);
    if (data.erro) throw new Error('CEP não encontrado');
    return { cep, street: data.logradouro, district: data.bairro, city: data.localidade, state: data.uf };
  },
  async (cep) => {
    const data = await getJson(`https://brasilapi.com.br/api/cep/v2/${cep}`);
    return { cep, street: data.street, district: data.neighborhood, city: data.city, state: data.state };
  },
  async (cep) => {
    const data = await getJson(`https://cep.awesomeapi.com.br/json/${cep}`);
    return { cep, street: data.address, district: data.district, city: data.city, state: data.state };
  },
];

export function lookupCep(cep: string): Promise<Address> {
  return Promise.any(providers.map((fetchFrom) => fetchFrom(cep)));
}

async function getJson(url: string) {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  return response.json();
}

export async function lookupCep(cep: string): Promise<Address> {
  const winner = new AbortController();

  const attempts = providers.map((fetchFrom) =>
    fetchFrom(cep, AbortSignal.any([winner.signal, AbortSignal.timeout(3000)])),
  );

  try {
    return await Promise.any(attempts);
  } finally {
    winner.abort();
  }
}
